CCE_IMAGE_B64 = """"""

def decode_embedded_cce_image() -> np.ndarray:
    """Decode the embedded CCE example image and convert it to a binary array."""
    raw = base64.b64decode(CCE_IMAGE_B64.encode("ascii"))
    img = Image.open(io.BytesIO(raw)).convert("L")
    arr = np.array(img)
    return arr > 127

