# ------------------------------------------------------------
# 6) Convex hull helper functions
# ------------------------------------------------------------
CONVEX_DATA_DIR = DATA_DIR
CONVEX_OUT_DIR = OUT_DIR
CONVEX_DATA_DIR.mkdir(exist_ok=True)
CONVEX_OUT_DIR.mkdir(exist_ok=True)

ART1BW_LOCAL = CONVEX_DATA_DIR / "art1bw.bmp"

# Fallback image extracted from the provided slide so the code runs
# even if art1bw.bmp is not available in Colab.
FALLBACK_B64 = ""

def load_art1bw_like_image() -> tuple[np.ndarray, str]:
    """Load art1bw.bmp if available; otherwise use the embedded fallback image."""
    if ART1BW_LOCAL.exists():
        I = np.array(Image.open(ART1BW_LOCAL).convert("L"))
        return I, "art1bw.bmp"
    fallback = Image.open(io.BytesIO(base64.b64decode(FALLBACK_B64))).convert("L")
    I = np.array(fallback)
    return I, "embedded fallback extracted from the slide"

def objects_convex_hull(bw: np.ndarray, connectivity: int = 2) -> np.ndarray:
    """Convex hull of each connected component, combined with logical OR."""
    labels = label(bw, connectivity=connectivity)
    out = np.zeros_like(bw, dtype=bool)
    for idx in range(1, labels.max() + 1):
        out |= convex_hull_image(labels == idx)
    return out

def run_convex_hull_experiment():
    I, source = load_art1bw_like_image()

    # Same threshold logic as the MATLAB slide: BW = I > 100
    BW = I > 100

    # Union convex hull (equivalent to bwconvhull(BW))
    CH = convex_hull_image(BW)

    # Objects convex hull (equivalent to bwconvhull(BW, 'objects'))
    CH_O = objects_convex_hull(BW, connectivity=2)

    fig, axes = plt.subplots(2, 2, figsize=(12, 8))
    axes[0, 0].imshow(I, cmap="gray")
    axes[0, 0].set_title(f"Original ({{source}})")
    axes[0, 0].axis("off")

    axes[0, 1].imshow(BW, cmap="gray")
    axes[0, 1].set_title("Binary")
    axes[0, 1].axis("off")

    axes[1, 0].imshow(CH, cmap="gray")
    axes[1, 0].set_title("Union Convex Hull")
    axes[1, 0].axis("off")

    axes[1, 1].imshow(CH_O, cmap="gray")
    axes[1, 1].set_title("Objects Convex Hull")
    axes[1, 1].axis("off")

    plt.tight_layout()
    save_fig(fig, "convex_hull_example_1.png")

    return I, BW, CH, CH_O

# ------------------------------------------------------------
