import numpy as np
from pathlib import Path
from PIL import Image
import urllib.request

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

from scipy.ndimage import binary_dilation, binary_erosion

from skimage import img_as_ubyte
from skimage.morphology import disk, opening, white_tophat, black_tophat
from skimage import exposure

DATA_DIR = Path("morphology_data")
OUT_DIR = Path("morphology_outputs")
DATA_DIR.mkdir(exist_ok=True)
OUT_DIR.mkdir(exist_ok=True)

RICE_PATH = DATA_DIR / "rice.png"
BRICK_PATH = DATA_DIR / "D1_256_8b.bmp"
SNOWFLAKES_PATH = DATA_DIR / "snowflakes2.png"
ART1BW_PATH = DATA_DIR / "art1bw_ic.bmp"
CIRCLES_URL = "https://raw.githubusercontent.com/camieac/image-processing-matlab/master/lab06/images/circles.png"

def load_local_image(path: Path, mode: str = "L") -> np.ndarray:
    if not path.exists():
        raise FileNotFoundError(f"Missing required asset: {path}")
    return np.array(Image.open(path).convert(mode))


def download_if_needed(url: str, path: Path) -> None:
    if not path.exists():
        print(f"Downloading {path.name} ...")
        urllib.request.urlretrieve(url, path)


def save_fig(fig, name: str) -> None:
    fig.savefig(OUT_DIR / name, dpi=220, bbox_inches="tight")
    plt.close(fig)

def run_boundary_extraction_experiment():
    circles_path = DATA_DIR / "circles.png"
    download_if_needed(CIRCLES_URL, circles_path)
    x = np.array(Image.open(circles_path).convert("L")) > 0
    se = disk(2)
    y = binary_erosion(x, structure=se)
    z = x & (~y)
    fig, axes = plt.subplots(1, 2, figsize=(10, 5))
    axes[0].imshow(x, cmap="gray", vmin=0, vmax=1)
    axes[0].set_title("Original circles image")
    axes[0].axis("off")
    axes[1].imshow(z, cmap="gray", vmin=0, vmax=1)
    axes[1].set_title("Boundary extraction")
    axes[1].axis("off")
    plt.tight_layout(); save_fig(fig, "boundary_extraction.png")
    return x, y, z

def run_region_filling_experiment():
    circles_path = DATA_DIR / "circles.png"
    download_if_needed(CIRCLES_URL, circles_path)
    A = np.array(Image.open(circles_path).convert("L")) > 0
    se = disk(2)
    Xk = np.zeros_like(A, dtype=bool)
    Xk1 = Xk.copy()
    Xk[54, 53] = True  # MATLAB (55,54)
    iterations = 0
    while not np.array_equal(Xk, Xk1):
        Xk1 = Xk.copy()
        Xk = binary_dilation(Xk1, structure=se) & (~A)
        iterations += 1
    A1 = Xk | A
    fig, axes = plt.subplots(1, 2, figsize=(10, 5))
    axes[0].imshow(A, cmap="gray", vmin=0, vmax=1)
    axes[0].set_title("Original circles image")
    axes[0].axis("off")
    axes[1].imshow(A1, cmap="gray", vmin=0, vmax=1)
    axes[1].set_title(f"Region filled image (iters={iterations})")
    axes[1].axis("off")
    plt.tight_layout(); save_fig(fig, "region_filling.png")
    return A, Xk, A1, iterations

def run_cce_experiment():
    IC = load_local_image(ART1BW_PATH, mode="L")
    I = 255 - IC
    BW = I > 100
    se = disk(2)
    Xk = np.zeros_like(BW, dtype=bool)
    Xk1 = Xk.copy()
    Xk[223, 194] = True  # MATLAB (224,195)
    iterations = 0
    while not np.array_equal(Xk, Xk1):
        Xk1 = Xk.copy()
        Xk = binary_dilation(Xk1, structure=se) & BW
        iterations += 1
    A1 = Xk
    fig, axes = plt.subplots(1, 3, figsize=(14, 5))
    axes[0].imshow(I, cmap="gray")
    axes[0].set_title("Complemented image")
    axes[0].axis("off")
    axes[1].imshow(BW, cmap="gray", vmin=0, vmax=1)
    axes[1].set_title("Binary image")
    axes[1].axis("off")
    axes[2].imshow(A1, cmap="gray", vmin=0, vmax=1)
    axes[2].set_title(f"CCE result (iters={iterations})")
    axes[2].axis("off")
    plt.tight_layout(); save_fig(fig, "cce_result.png")
    return IC, I, BW, A1, iterations

def run_top_hat_experiment():
    im = load_local_image(RICE_PATH, mode="L")
    se = disk(12)
    J = white_tophat(im, footprint=se)
    K = exposure.rescale_intensity(J, in_range="image", out_range=(0, 255)).astype(np.uint8)
    fig, axes = plt.subplots(1, 3, figsize=(14, 5))
    axes[0].imshow(im, cmap="gray")
    axes[0].set_title("Original image")
    axes[0].axis("off")
    axes[1].imshow(J, cmap="gray")
    axes[1].set_title("Top-hat result")
    axes[1].axis("off")
    axes[2].imshow(K, cmap="gray")
    axes[2].set_title("Adjusted image")
    axes[2].axis("off")
    plt.tight_layout(); save_fig(fig, "tophat_results.png")
    return im, J, K


def run_bottom_hat_experiment():
    im = load_local_image(BRICK_PATH, mode="L")
    se = disk(32)
    J = black_tophat(im, footprint=se)
    fig, axes = plt.subplots(1, 2, figsize=(12, 5))
    axes[0].imshow(im, cmap="gray")
    axes[0].set_title("Original image")
    axes[0].axis("off")
    axes[1].imshow(J, cmap="gray")
    axes[1].set_title("Bottom-hat result")
    axes[1].axis("off")
    plt.tight_layout(); save_fig(fig, "bottomhat_results.png")
    return im, J

def run_granulometry_experiment():
    im = load_local_image(SNOWFLAKES_PATH, mode="L")
    clahel = exposure.equalize_adapthist(im, kernel_size=(10, 10), clip_limit=0.01)
    clahel = exposure.rescale_intensity(clahel, in_range="image", out_range=(0, 1))
    intensity_area = []
    for counter in range(23):
        fp = disk(counter) if counter > 0 else np.ones((1, 1), dtype=bool)
        remain = opening(clahel, footprint=fp)
        intensity_area.append(float(np.sum(remain)))
    intensity_area = np.array(intensity_area)
    open5 = opening(clahel, footprint=disk(5))
    open6 = opening(clahel, footprint=disk(6))
    rad5 = np.clip(open5 - open6, 0, 1)
    fig, axes = plt.subplots(2, 2, figsize=(14, 10))
    axes[0, 0].imshow(im, cmap="gray")
    axes[0, 0].set_title("Original image")
    axes[0, 0].axis("off")
    axes[0, 1].imshow(clahel, cmap="gray")
    axes[0, 1].set_title("Contrast-enhanced image")
    axes[0, 1].axis("off")
    axes[1, 0].plot(intensity_area, "m-*")
    axes[1, 0].grid(True)
    axes[1, 0].set_title("Granulometry curve")
    axes[1, 0].set_xlabel("Radius of opening")
    axes[1, 0].set_ylabel("Sum of pixel values after opening")
    axes[1, 1].imshow(rad5, cmap="gray")
    axes[1, 1].set_title("Size-extracted image (r=5 minus r=6)")
    axes[1, 1].axis("off")
    plt.tight_layout(); save_fig(fig, "granulometry_results.png")
    return im, clahel, intensity_area, rad5

def main():
    boundary = run_boundary_extraction_experiment()
    region = run_region_filling_experiment()
    cce = run_cce_experiment()
    tophat = run_top_hat_experiment()
    bottomhat = run_bottom_hat_experiment()
    gran = run_granulometry_experiment()
    print(f"Figures saved into: {OUT_DIR.resolve()}")
    return {"boundary": boundary, "region": region, "cce": cce, "tophat": tophat, "bottomhat": bottomhat, "granulometry": gran}


if __name__ == "__main__":
    main()

from IPython.display import Image, display
for name in ["boundary_extraction.png", "region_filling.png", "cce_result.png", "tophat_results.png", "bottomhat_results.png", "granulometry_results.png"]:
    display(Image(filename=str(OUT_DIR / name)))

