"""
Morphological Image Processing: Three additional exercises
1) Thinning
2) Skeletonization
3) Connected Components Extraction

Self-contained Google Colab / Python script.
No input files are required: all demo images are generated synthetically.
"""

# ------------------------------------------------------------
# 1) Installation note for Colab
# ------------------------------------------------------------
# !pip install -q numpy matplotlib scipy scikit-image pillow

import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

from pathlib import Path
from scipy.ndimage import binary_dilation, binary_erosion
from skimage.draw import line
from skimage.morphology import disk

# ------------------------------------------------------------
# 2) Output directory
# ------------------------------------------------------------
OUT_DIR = Path("morphology_outputs_three")
OUT_DIR.mkdir(exist_ok=True)

def save_fig(fig, name: str) -> None:
    fig.savefig(OUT_DIR / name, dpi=220, bbox_inches="tight")
    plt.close(fig)

# ------------------------------------------------------------
# 3) Helper utilities
# ------------------------------------------------------------
def _as_bool(image: np.ndarray) -> np.ndarray:
    image = np.asarray(image)
    if image.dtype != bool:
        image = image > 0
    return image

def draw_thick_line(img: np.ndarray, p0, p1, radius: int = 6) -> None:
    rr, cc = line(p0[0], p0[1], p1[0], p1[1])
    img[rr, cc] = True
    img[:] = binary_dilation(img, structure=disk(radius))

# ------------------------------------------------------------
# 4) Exercise 6: Thinning
#    Classical iterative thinning (Zhang-Suen) from scratch.
# ------------------------------------------------------------
def zhang_suen_thinning(image: np.ndarray) -> np.ndarray:
    """
    Iterative thinning until convergence.
    Input: binary image (bool or 0/1)
    Output: thinned binary image (bool)
    """
    img = _as_bool(image).astype(np.uint8)

    def step(subimg: np.ndarray, iteration: int) -> np.ndarray:
        p2 = subimg[:-2, 1:-1]
        p3 = subimg[:-2, 2:]
        p4 = subimg[1:-1, 2:]
        p5 = subimg[2:, 2:]
        p6 = subimg[2:, 1:-1]
        p7 = subimg[2:, :-2]
        p8 = subimg[1:-1, :-2]
        p9 = subimg[:-2, :-2]
        p1 = subimg[1:-1, 1:-1]

        bp1 = p2 + p3 + p4 + p5 + p6 + p7 + p8 + p9

        ap1 = (
            ((p2 == 0) & (p3 == 1)).astype(np.uint8)
            + ((p3 == 0) & (p4 == 1)).astype(np.uint8)
            + ((p4 == 0) & (p5 == 1)).astype(np.uint8)
            + ((p5 == 0) & (p6 == 1)).astype(np.uint8)
            + ((p6 == 0) & (p7 == 1)).astype(np.uint8)
            + ((p7 == 0) & (p8 == 1)).astype(np.uint8)
            + ((p8 == 0) & (p9 == 1)).astype(np.uint8)
            + ((p9 == 0) & (p2 == 1)).astype(np.uint8)
        )

        if iteration == 0:
            m = (
                (p1 == 1)
                & (bp1 >= 2) & (bp1 <= 6)
                & (ap1 == 1)
                & ((p2 * p4 * p6) == 0)
                & ((p4 * p6 * p8) == 0)
            )
        else:
            m = (
                (p1 == 1)
                & (bp1 >= 2) & (bp1 <= 6)
                & (ap1 == 1)
                & ((p2 * p4 * p8) == 0)
                & ((p2 * p6 * p8) == 0)
            )
        return m

    changed = True
    while changed:
        before = img.copy()

        # First sub-iteration
        m = step(img, 0)
        img[1:-1, 1:-1][m] = 0

        # Second sub-iteration
        m = step(img, 1)
        img[1:-1, 1:-1][m] = 0

        changed = not np.array_equal(before, img)

    return img.astype(bool)

def make_thinning_demo_image() -> np.ndarray:
    """
    A thick Y-shaped object with an extra bar, so thinning is easy to see.
    """
    img = np.zeros((256, 256), dtype=bool)

    segments = [
        ((40, 60), (120, 128)),
        ((40, 196), (120, 128)),
        ((120, 128), (215, 128)),
        ((170, 75), (215, 75)),
        ((170, 181), (215, 181)),
    ]
    for p0, p1 in segments:
        rr, cc = line(p0[0], p0[1], p1[0], p1[1])
        img[rr, cc] = True

    # Thicken the centerlines to create a proper binary object.
    img = binary_dilation(img, structure=disk(10))
    return img

def run_thinning_experiment():
    bw = make_thinning_demo_image()
    thin_bw = zhang_suen_thinning(bw)

    fig, axes = plt.subplots(1, 2, figsize=(12, 6))
    axes[0].imshow(bw, cmap="gray", vmin=0, vmax=1)
    axes[0].set_title("Input binary object")
    axes[0].axis("off")

    axes[1].imshow(thin_bw, cmap="gray", vmin=0, vmax=1)
    axes[1].set_title("Thinning result")
    axes[1].axis("off")

    plt.tight_layout()
    save_fig(fig, "thinning_result.png")
    return bw, thin_bw

# ------------------------------------------------------------
# 5) Exercise 7: Skeletonization
#    Morphological skeleton using erosions and openings.
# ------------------------------------------------------------
def morphological_skeleton(image: np.ndarray, se: np.ndarray | None = None):
    """
    Skeleton of a binary image:
        S(A) = union_k [ (A ⊖ kB) - ((A ⊖ kB) ○ B) ]
    Implemented by repeated erosions until the set becomes empty.
    """
    A = _as_bool(image)
    if se is None:
        se = np.ones((3, 3), dtype=bool)

    skel = np.zeros_like(A, dtype=bool)
    current = A.copy()

    while current.any():
        eroded = binary_erosion(current, structure=se)
        opened = binary_dilation(binary_erosion(current, structure=se), structure=se)
        residue = current & (~opened)
        skel |= residue
        current = eroded

    return skel

def make_skeleton_demo_image() -> np.ndarray:
    """
    A thicker region made from overlapping disks and bars.
    The medial axis becomes visible after skeletonization.
    """
    img = np.zeros((260, 260), dtype=bool)

    # A thick curvy structure made from connected line segments.
    points = [
        (40, 40),
        (95, 75),
        (135, 110),
        (175, 80),
        (220, 40),
        (180, 140),
        (135, 180),
        (90, 140),
        (55, 190),
    ]
    for p0, p1 in zip(points[:-1], points[1:]):
        rr, cc = line(p0[0], p0[1], p1[0], p1[1])
        img[rr, cc] = True

    # Make it a filled thick object.
    img = binary_dilation(img, structure=disk(14))

    # Add a circular bulge to make the skeleton interesting.
    rr, cc = np.ogrid[:260, :260]
    blob = (rr - 145) ** 2 + (cc - 120) ** 2 <= 28 ** 2
    img |= blob
    img = binary_dilation(img, structure=disk(3))
    return img

def run_skeletonization_experiment():
    bw = make_skeleton_demo_image()
    skel = morphological_skeleton(bw, se=np.ones((3, 3), dtype=bool))

    fig, axes = plt.subplots(1, 2, figsize=(12, 6))
    axes[0].imshow(bw, cmap="gray", vmin=0, vmax=1)
    axes[0].set_title("Input binary object")
    axes[0].axis("off")

    axes[1].imshow(skel, cmap="gray", vmin=0, vmax=1)
    axes[1].set_title("Skeletonization result")
    axes[1].axis("off")

    plt.tight_layout()
    save_fig(fig, "skeletonization_result.png")
    return bw, skel

# ------------------------------------------------------------
# 6) Exercise 8: Connected Components Extraction
#    X0 = p
#    Xk = (Xk ⊕ B) ∩ A   until convergence
# ------------------------------------------------------------
def extract_connected_component(A: np.ndarray, seed: tuple[int, int], se: np.ndarray | None = None):
    """
    Morphological connected component extraction by iterative geodesic dilation.
    A: binary mask of the whole image
    seed: (row, col) point inside the desired connected component
    """
    A = _as_bool(A)
    if se is None:
        # 8-connected neighborhood
        se = np.ones((3, 3), dtype=bool)

    r, c = seed
    if not A[r, c]:
        raise ValueError("The seed point must lie inside the foreground object A.")

    X = np.zeros_like(A, dtype=bool)
    X[r, c] = True

    while True:
        prev = X.copy()
        X = binary_dilation(X, structure=se) & A
        if np.array_equal(X, prev):
            break

    return X

def make_connected_components_image():
    """
    Synthetic binary image containing several separate components.
    We choose one seed and extract only its connected region.
    """
    img = np.zeros((220, 300), dtype=bool)

    # Component 1: left rounded blob
    rr, cc = np.ogrid[:220, :300]
    blob1 = (rr - 65) ** 2 + (cc - 55) ** 2 <= 34 ** 2
    img |= blob1

    # Component 2: a diagonal thick object
    seg = np.zeros_like(img)
    pts = [(30, 150), (70, 185), (110, 220), (145, 245), (180, 260)]
    # Fix last point to stay in image bounds:
    pts = [(30, 150), (70, 185), (110, 220), (145, 245), (180, 250)]
    for p0, p1 in zip(pts[:-1], pts[1:]):
        rr, cc = line(p0[0], p0[1], p1[0], p1[1])
        seg[rr, cc] = True
    seg = binary_dilation(seg, structure=disk(10))
    img |= seg

    # Component 3: a small rectangle
    img[150:190, 35:95] = True
    img = binary_dilation(img, structure=disk(2))

    # A few isolated points as distractors
    for p in [(15, 20), (200, 285), (120, 20), (40, 260)]:
        img[p] = True

    seed = (78, 56)  # inside the left blob
    return img, seed

def run_connected_components_experiment():
    A, seed = make_connected_components_image()
    comp = extract_connected_component(A, seed, se=np.ones((3, 3), dtype=bool))

    fig, axes = plt.subplots(1, 2, figsize=(13, 6))
    axes[0].imshow(A, cmap="gray", vmin=0, vmax=1)
    axes[0].plot(seed[1], seed[0], "ro", markersize=6)
    axes[0].set_title("Original binary image + seed")
    axes[0].axis("off")

    axes[1].imshow(comp, cmap="gray", vmin=0, vmax=1)
    axes[1].set_title("Extracted connected component")
    axes[1].axis("off")

    plt.tight_layout()
    save_fig(fig, "connected_component_result.png")
    return A, seed, comp

# ------------------------------------------------------------
# 7) Main
# ------------------------------------------------------------
def main():
    bw_thin, thin_res = run_thinning_experiment()
    bw_skel, skel_res = run_skeletonization_experiment()
    A, seed, cc_res = run_connected_components_experiment()

    print("Saved figures in:", OUT_DIR.resolve())
    print("Thinning foreground pixels:", int(bw_thin.sum()), "->", int(thin_res.sum()))
    print("Skeleton foreground pixels:", int(bw_skel.sum()), "->", int(skel_res.sum()))
    print("Connected component pixels:", int(A.sum()), "->", int(cc_res.sum()))

if __name__ == "__main__":
    main()

