def show_saved(name: str) -> None:
    """Display a saved image in Colab/Jupyter."""
    display(IPyImage(filename=str(OUT_DIR / name)))


# ------------------------------------------------------------
# Basic binary-image helpers
# ------------------------------------------------------------
def to_bool_image(pil_img: Image.Image) -> np.ndarray:
    return np.array(pil_img) > 0


def pad_bool(img: np.ndarray, pad: int = 1) -> np.ndarray:
    return np.pad(img, pad_width=pad, mode="constant", constant_values=False)


def neighbors_8(img: np.ndarray) -> np.ndarray:
    """
    Count 8-neighbors for each pixel (center pixel excluded).
    Returns an array with the same shape as img.
    """
    k = np.ones((3, 3), dtype=np.uint8)
    return ndi.convolve(img.astype(np.uint8), k, mode="constant", cval=0) - img.astype(np.uint8)


# ------------------------------------------------------------
# 1) Thinning from scratch (Zhang-Suen)
# ------------------------------------------------------------
def zhang_suen_thinning(binary: np.ndarray) -> np.ndarray:
    """
    Iterative thinning algorithm that reduces foreground objects to 1-pixel-wide strokes.
    This is a classic from-scratch implementation of Zhang-Suen thinning.
    """
    img = binary.copy().astype(bool)
    changed = True

    while changed:
        changed = False

        for step in (0, 1):
            P1 = img[1:-1, 1:-1]
            P2 = img[:-2, 1:-1]
            P3 = img[:-2, 2:]
            P4 = img[1:-1, 2:]
            P5 = img[2:, 2:]
            P6 = img[2:, 1:-1]
            P7 = img[2:, :-2]
            P8 = img[1:-1, :-2]
            P9 = img[:-2, :-2]

            neighbors = (
                P2.astype(np.uint8) + P3.astype(np.uint8) + P4.astype(np.uint8) +
                P5.astype(np.uint8) + P6.astype(np.uint8) + P7.astype(np.uint8) +
                P8.astype(np.uint8) + P9.astype(np.uint8)
            )

            transitions = (
                ((~P2) & P3).astype(np.uint8) +
                ((~P3) & P4).astype(np.uint8) +
                ((~P4) & P5).astype(np.uint8) +
                ((~P5) & P6).astype(np.uint8) +
                ((~P6) & P7).astype(np.uint8) +
                ((~P7) & P8).astype(np.uint8) +
                ((~P8) & P9).astype(np.uint8) +
                ((~P9) & P2).astype(np.uint8)
            )

            cond = P1 & (neighbors >= 2) & (neighbors <= 6) & (transitions == 1)

            if step == 0:
                cond &= ~(P2 & P4 & P6) & ~(P4 & P6 & P8)
            else:
                cond &= ~(P2 & P4 & P8) & ~(P2 & P6 & P8)

            if np.any(cond):
                img[1:-1, 1:-1][cond] = False
                changed = True

    return img


# ------------------------------------------------------------
# 2) Pruning from scratch
#    Pruning = thinning + successive endpoint deletion
# ------------------------------------------------------------
def endpoint_mask(skeleton: np.ndarray) -> np.ndarray:
    """
    Endpoints are foreground pixels with exactly one 8-neighbor.
    """
    return skeleton & (neighbors_8(skeleton) == 1)


def prune_skeleton(binary: np.ndarray, iterations: int = 8):
    """
    Prune a binary object:
    1) thin it to a skeleton
    2) repeatedly delete endpoints for a fixed number of iterations

    This removes short parasitic branches while preserving the main structure.
    """
    skel = zhang_suen_thinning(binary)
    history = [skel.copy()]

    for _ in range(iterations):
        ep = endpoint_mask(skel)
        if not ep.any():
            break
        skel = skel & ~ep
        history.append(skel.copy())

    return skel, history


# ------------------------------------------------------------
# 3) Thickening from scratch
#    A clean, Colab-friendly growth operator.
#    This is an explicit 8-connected binary growth that visually
#    demonstrates the "thickening" effect used in morphology.
# ------------------------------------------------------------
def dilate8_once(binary: np.ndarray) -> np.ndarray:
    """
    One iteration of 8-connected binary growth using a 3x3 all-ones neighborhood.
    """
    p = pad_bool(binary, 1)
    h, w = binary.shape
    out = np.zeros_like(binary, dtype=bool)

    for di in range(3):
        for dj in range(3):
            out |= p[di:di + h, dj:dj + w]
    return out


def thickening(binary: np.ndarray, iterations: int = 2) -> np.ndarray:
    """
    Grow the foreground by repeated 8-neighborhood expansion.

    Note:
    In MATLAB/Gonzalez-Woods, thickening is described as a dual morphological
    operator related to hit-or-miss. Here we implement a simple from-scratch
    binary-growth version that clearly shows the thickening effect in Colab.
    """
    out = binary.copy()
    for _ in range(iterations):
        out = dilate8_once(out)
    return out


