def make_pruning_demo(size: int = 160) -> np.ndarray:
    """
    A branch-like shape with short parasitic spurs.
    Pruning should remove the short branches first.
    """
    img = Image.new("L", (size, size), 0)
    d = ImageDraw.Draw(img)

    # Main structure
    d.line((30, 130, 70, 90), fill=255, width=9)
    d.line((70, 90, 110, 50), fill=255, width=9)
    d.line((70, 90, 110, 130), fill=255, width=9)

    # Short parasitic branches
    d.line((50, 110, 62, 98), fill=255, width=7)
    d.line((92, 68, 103, 57), fill=255, width=7)
    d.line((98, 114, 112, 128), fill=255, width=7)
    d.line((70, 90, 70, 72), fill=255, width=5)

    return to_bool_image(img)


def make_thinning_demo(size: int = 160) -> np.ndarray:
    """
    Thick capital A for thinning.
    """
    img = Image.new("L", (size, size), 0)
    d = ImageDraw.Draw(img)

    d.line((35, 130, 80, 30), fill=255, width=16)
    d.line((80, 30, 125, 130), fill=255, width=16)
    d.line((52, 86, 108, 86), fill=255, width=16)

    # small detail to make the skeleton interesting
    d.rectangle((74, 52, 86, 64), fill=255)

    return to_bool_image(img)


def make_thickening_demo(size: int = 160) -> np.ndarray:
    """
    Thin open contour and a diagonal stroke.
    Thickening should broaden the strokes and slightly bridge the open side.
    """
    img = Image.new("L", (size, size), 0)
    d = ImageDraw.Draw(img)

    d.line((35, 45, 120, 45), fill=255, width=3)
    d.line((120, 45, 40, 115), fill=255, width=3)
    d.line((40, 115, 125, 115), fill=255, width=3)
    d.line((80, 60, 95, 90), fill=255, width=3)

    return to_bool_image(img)


