# ------------------------------------------------------------
# Exercise 4: Translation, Reflection, Complement, Difference
# ------------------------------------------------------------
def make_set_ops_demo(size: int = 160):
    """
    Build two binary sets:
    - A: asymmetric object for translation / reflection / complement
    - B: a strict subset of A for difference A - B
    """
    canvas = Image.new("L", (size, size), 0)
    draw = ImageDraw.Draw(canvas)

    # Asymmetric set A
    draw.rectangle([18, 20, 72, 58], fill=255)           # main body
    draw.ellipse([92, 24, 132, 64], fill=255)            # circle
    draw.polygon([(40, 84), (58, 62), (76, 86)], fill=255)  # triangle
    draw.line([88, 86, 130, 112], fill=255, width=6)     # diagonal bar
    draw.rectangle([18, 105, 44, 132], fill=255)         # lower-left block

    A = np.array(canvas) > 0

    # Subset B fully inside the rectangle part of A
    subset = Image.new("L", (size, size), 0)
    sdraw = ImageDraw.Draw(subset)
    sdraw.rectangle([30, 30, 54, 47], fill=255)
    B = np.array(subset) > 0

    return A, B


def translate_binary(img: np.ndarray, dx: int, dy: int, canvas_shape=None) -> np.ndarray:
    """
    Translate a binary image by (dx, dy) on a zero-padded canvas.
    dx > 0 moves right, dy > 0 moves down.
    """
    if canvas_shape is None:
        canvas_shape = img.shape

    out = np.zeros(canvas_shape, dtype=bool)

    src_y0 = max(0, -dy)
    src_x0 = max(0, -dx)
    dst_y0 = max(0, dy)
    dst_x0 = max(0, dx)

    h = min(img.shape[0] - src_y0, canvas_shape[0] - dst_y0)
    w = min(img.shape[1] - src_x0, canvas_shape[1] - dst_x0)

    if h > 0 and w > 0:
        out[dst_y0:dst_y0 + h, dst_x0:dst_x0 + w] = img[src_y0:src_y0 + h, src_x0:src_x0 + w]

    return out


def reflect_about_origin(img: np.ndarray) -> np.ndarray:
    """
    Reflection about the origin: (x, y) -> (-x, -y).
    For an image array, this is equivalent to flipping both axes.
    """
    return np.flipud(np.fliplr(img))


def complement_binary(img: np.ndarray) -> np.ndarray:
    """Set complement on the same canvas."""
    return np.logical_not(img)


def difference_binary(A: np.ndarray, B: np.ndarray) -> np.ndarray:
    """Set difference A - B = A ∩ B^c."""
    return np.logical_and(A, np.logical_not(B))


def run_set_operations_experiment():
    A, B = make_set_ops_demo()

    translated = translate_binary(A, dx=28, dy=20, canvas_shape=A.shape)
    reflected = reflect_about_origin(A)
    complemented = complement_binary(A)
    diff = difference_binary(A, B)

    fig, axes = plt.subplots(2, 3, figsize=(14, 9))

    axes[0, 0].imshow(A, cmap="gray", vmin=0, vmax=1)
    axes[0, 0].set_title("A: Original set")
    axes[0, 0].axis("off")

    axes[0, 1].imshow(translated, cmap="gray", vmin=0, vmax=1)
    axes[0, 1].set_title(r"Translation $A_z$  (dx=28, dy=20)")
    axes[0, 1].axis("off")

    axes[0, 2].imshow(reflected, cmap="gray", vmin=0, vmax=1)
    axes[0, 2].set_title(r"Reflection $\hat{A}$ about origin")
    axes[0, 2].axis("off")

    axes[1, 0].imshow(complemented, cmap="gray", vmin=0, vmax=1)
    axes[1, 0].set_title(r"Complement $A^c$")
    axes[1, 0].axis("off")

    axes[1, 1].imshow(B, cmap="gray", vmin=0, vmax=1)
    axes[1, 1].set_title("B: Subset of A")
    axes[1, 1].axis("off")

    axes[1, 2].imshow(diff, cmap="gray", vmin=0, vmax=1)
    axes[1, 2].set_title(r"Difference $A - B$")
    axes[1, 2].axis("off")

    plt.tight_layout()
    save_fig(fig, "set_operations_demo.png")
    return A, B, translated, reflected, complemented, diff


def main():
    run_pruning_experiment()
    run_thinning_experiment()
    run_thickening_experiment()
    run_set_operations_experiment()

    print(f"All figures saved into: {OUT_DIR.resolve()}")


if __name__ == "__main__":
    main()


