import numpy as np
import matplotlib.pyplot as plt
from pathlib import Path
from scipy import ndimage as ndi
from skimage import img_as_ubyte
from skimage.draw import disk as draw_disk
from skimage.morphology import (
    disk,
    square,
    erosion,
    dilation,
    opening,
    closing,
)
from skimage.util import random_noise
from skimage.filters import gaussian
from PIL import Image

plt.rcParams["figure.figsize"] = (10, 6)
plt.rcParams["figure.dpi"] = 120

OUT_DIR = Path("morphology_addendum_outputs")
OUT_DIR.mkdir(exist_ok=True)


def save_fig(fig, name: str):
    fig.savefig(OUT_DIR / name, bbox_inches="tight", dpi=200)
    plt.close(fig)


def to_float01(img):
    img = np.asarray(img, dtype=np.float32)
    if img.max() > 1.0:
        img = img / 255.0
    return np.clip(img, 0.0, 1.0)


# ------------------------------------------------------------
# 1) Synthetic image for smoothing and gradient
# ------------------------------------------------------------
def create_synthetic_binary_image(seed=0):
    """Binary image with large objects + small noise; good for smoothing."""
    rng = np.random.default_rng(seed)
    img = np.zeros((256, 256), dtype=bool)

    # Large objects
    rr, cc = draw_disk((70, 75), 28, shape=img.shape)
    img[rr, cc] = True
    rr, cc = draw_disk((180, 170), 35, shape=img.shape)
    img[rr, cc] = True
    rr, cc = draw_disk((90, 190), 20, shape=img.shape)
    img[rr, cc] = True

    # Small holes / protrusions to make smoothing meaningful
    img[55:60, 65:70] = False
    img[170:176, 160:168] = False
    img[85:88, 185:191] = False

    # Random salt noise
    coords = rng.integers(0, 256, size=(220, 2))
    img[coords[:, 0], coords[:, 1]] = True
    coords = rng.integers(0, 256, size=(160, 2))
    img[coords[:, 0], coords[:, 1]] = False

    return img


def morph_smoothing(binary_img, se_radius=5):
    se = disk(se_radius)
    return closing(opening(binary_img, footprint=se), footprint=se)


def morph_gradient(binary_img, se_radius=3):
    se = disk(se_radius)
    dil = dilation(binary_img, footprint=se)
    ero = erosion(binary_img, footprint=se)
    return dil.astype(np.int16) - ero.astype(np.int16)


# ------------------------------------------------------------
# 2) Synthetic image for textural segmentation
# ------------------------------------------------------------
def create_textural_image(seed=1, size=512):
    """
    Build an image with two texture regions:
    - upper half: many small disks
    - lower half: fewer large disks
    Intensities are kept grayscale to resemble textbook examples.
    """
    rng = np.random.default_rng(seed)
    img = np.full((size, size), 0.18, dtype=np.float32)

    # Top region: small blobs
    for _ in range(420):
        r = rng.integers(2, 6)
        cy = rng.integers(0, size // 2)
        cx = rng.integers(0, size)
        rr, cc = draw_disk((cy, cx), r, shape=img.shape)
        img[rr, cc] = 0.68

    # Bottom region: large blobs
    for _ in range(90):
        r = rng.integers(7, 15)
        cy = rng.integers(size // 2, size)
        cx = rng.integers(0, size)
        rr, cc = draw_disk((cy, cx), r, shape=img.shape)
        img[rr, cc] = 0.75

    # Add mild noise / blur to look more realistic
    img = random_noise(img, mode="gaussian", var=0.003, clip=True)
    img = gaussian(img, sigma=0.6, preserve_range=True)
    return img.astype(np.float32)


# ------------------------------------------------------------
# 3) Gray-scale morphology with flat SE
# ------------------------------------------------------------
def gray_flat_demo():
    from skimage.data import camera
    img = img_as_ubyte(camera())
    img_f = to_float01(img)

    se = disk(9)
    ero = erosion(img_f, footprint=se)
    dil = dilation(img_f, footprint=se)
    opn = opening(img_f, footprint=se)
    cls = closing(img_f, footprint=se)

    fig, axes = plt.subplots(2, 3, figsize=(12, 8))
    axes = axes.ravel()
    axes[0].imshow(img_f, cmap="gray")
    axes[0].set_title("Original grayscale image")
    axes[1].imshow(ero, cmap="gray")
    axes[1].set_title("Erosion (flat disk)")
    axes[2].imshow(dil, cmap="gray")
    axes[2].set_title("Dilation (flat disk)")
    axes[3].imshow(opn, cmap="gray")
    axes[3].set_title("Opening")
    axes[4].imshow(cls, cmap="gray")
    axes[4].set_title("Closing")
    axes[5].axis("off")
    for ax in axes[:-1]:
        ax.axis("off")
    plt.tight_layout()
    save_fig(fig, "gray_flat_morphology.png")
    return img_f, ero, dil, opn, cls


# ------------------------------------------------------------
# 4) Gray-scale morphology with nonflat SE
# ------------------------------------------------------------
def nonflat_structuring_element(kind="paraboloid", radius=7):
    """Create a nonflat SE as a 2D float array."""
    y, x = np.mgrid[-radius:radius+1, -radius:radius+1]
    d2 = x**2 + y**2
    if kind == "paraboloid":
        b = -0.02 * d2
    elif kind == "cone":
        b = -0.08 * np.sqrt(d2)
    else:
        raise ValueError("Unsupported kind")

    # Outside the circular support, mark as NaN so it is ignored.
    mask = d2 <= radius**2
    b = np.where(mask, b, np.nan)
    return b.astype(np.float32)


def nonflat_erosion(image, b):
    """Nonflat grayscale erosion: min(f - b). NaN positions are ignored."""
    image = image.astype(np.float32)
    kh, kw = b.shape
    ph, pw = kh // 2, kw // 2
    padded = np.pad(image, ((ph, ph), (pw, pw)), mode="edge")
    out = np.zeros_like(image, dtype=np.float32)

    valid = ~np.isnan(b)
    b_valid = b[valid]

    for i in range(image.shape[0]):
        for j in range(image.shape[1]):
            patch = padded[i:i+kh, j:j+kw]
            vals = patch[valid] - b_valid
            out[i, j] = np.min(vals)
    return out


def nonflat_dilation(image, b):
    """Nonflat grayscale dilation: max(f + b). NaN positions are ignored."""
    image = image.astype(np.float32)
    kh, kw = b.shape
    ph, pw = kh // 2, kw // 2
    padded = np.pad(image, ((ph, ph), (pw, pw)), mode="edge")
    out = np.zeros_like(image, dtype=np.float32)

    valid = ~np.isnan(b)
    b_valid = b[valid]

    for i in range(image.shape[0]):
        for j in range(image.shape[1]):
            patch = padded[i:i+kh, j:j+kw]
            vals = patch[valid] + b_valid
            out[i, j] = np.max(vals)
    return out


def run_nonflat_demo():
    from skimage.data import camera
    img = to_float01(camera())

    b = nonflat_structuring_element(kind="paraboloid", radius=7)
    ero_nf = nonflat_erosion(img, b)
    dil_nf = nonflat_dilation(img, b)

    fig, axes = plt.subplots(1, 3, figsize=(13, 5))
    axes[0].imshow(img, cmap="gray")
    axes[0].set_title("Original grayscale image")
    axes[1].imshow(ero_nf, cmap="gray")
    axes[1].set_title("Nonflat erosion")
    axes[2].imshow(dil_nf, cmap="gray")
    axes[2].set_title("Nonflat dilation")
    for ax in axes:
        ax.axis("off")
    plt.tight_layout()
    save_fig(fig, "gray_nonflat_morphology.png")
    return img, b, ero_nf, dil_nf


# ------------------------------------------------------------
# 5) Textural segmentation pipeline
# ------------------------------------------------------------
def run_textural_segmentation():
    img = create_textural_image(seed=10, size=512)

    # Step 1: remove small blobs by closing
    closed = closing(img, footprint=disk(5))

    # Step 2: remove light patches between large blobs by opening
    opened = opening(closed, footprint=disk(11))

    # Step 3: morphological gradient for boundary extraction
    grad = dilation(opened, footprint=disk(3)) - erosion(opened, footprint=disk(3))
    boundary = grad > (0.12 * grad.max())

    # Overlay boundary on the original image
    overlay = np.dstack([img, img, img])
    overlay[boundary, 0] = 1.0
    overlay[boundary, 1] = 0.0
    overlay[boundary, 2] = 0.0

    fig, axes = plt.subplots(2, 2, figsize=(12, 12))
    axes[0, 0].imshow(img, cmap="gray")
    axes[0, 0].set_title("(a) Original synthetic texture image")
    axes[0, 1].imshow(closed, cmap="gray")
    axes[0, 1].set_title("(b) After closing")
    axes[1, 0].imshow(opened, cmap="gray")
    axes[1, 0].set_title("(c) After opening")
    axes[1, 1].imshow(overlay)
    axes[1, 1].set_title("(d) Boundary superimposed")
    for ax in axes.ravel():
        ax.axis("off")
    plt.tight_layout()
    save_fig(fig, "textural_segmentation.png")

    # Additional figure: gradient map
    fig2, ax2 = plt.subplots(1, 1, figsize=(8, 6))
    ax2.imshow(grad, cmap="gray")
    ax2.set_title("Morphological gradient used for boundary extraction")
    ax2.axis("off")
    plt.tight_layout()
    save_fig(fig2, "textural_gradient.png")

    return img, closed, opened, grad, boundary, overlay


# ------------------------------------------------------------
# 6) Morphological smoothing demo
# ------------------------------------------------------------
def run_smoothing_demo(seed=0):
    img = create_synthetic_binary_image(seed=seed)
    smoothed = morph_smoothing(img, se_radius=5)
    gradient = morph_gradient(smoothed, se_radius=3)

    fig, axes = plt.subplots(1, 3, figsize=(15, 5))
    axes[0].imshow(img, cmap="gray")
    axes[0].set_title("Original binary image")
    axes[1].imshow(smoothed, cmap="gray")
    axes[1].set_title("Morphological smoothing")
    axes[2].imshow(gradient, cmap="gray")
    axes[2].set_title("Morphological gradient")
    for ax in axes:
        ax.axis("off")
    plt.tight_layout()
    save_fig(fig, f"smooth_gradient_seed_{seed}.png")
    return img, smoothed, gradient


# ------------------------------------------------------------
# 7) Run everything
# ------------------------------------------------------------
def main():
    # Smoothing + gradient
    run_smoothing_demo(seed=3)

    # Textural segmentation
    run_textural_segmentation()

    # Gray-scale morphology, flat SE
    gray_flat_demo()

    # Gray-scale morphology, nonflat SE
    run_nonflat_demo()

    print(f"All figures saved in: {OUT_DIR.resolve()}")


if __name__ == "__main__":
    main()

